#!/usr/bin/env python3
"""Generate public method invocations; endpoint expectations remain independent spec fixtures."""
from pathlib import Path
import json,sys
root=Path(__file__).resolve().parents[1];ops=json.loads((root/'spec/core-operations.json').read_text())
lines=['// <auto-generated>Public endpoint invocations for pinned-spec operations.</auto-generated>','#nullable enable','using System.Text.Json;','using System.Text.Json.Nodes;','using Kirora.Models;','','namespace Kirora.Tests;','','internal static class ExtendedEndpointInvoker','{','    internal static async Task<object?> Invoke(KiroraClient client, string operation, JsonNode? body, KiroraRequestOptions? options, CancellationToken cancellationToken)','    {','        var fixture = CoreContractTests.Fixture(operation);','        T Read<T>() => body is null ? default! : body.Deserialize<T>(CoreContractTests.Json)!;','        T Query<T>() => fixture["query"]!.Deserialize<T>(CoreContractTests.Json)!;','        string Path(string name) => fixture["pathValues"]![name]!.GetValue<string>();','        switch (operation)','        {']
for o in ops:
 args=[f'Path("{p}")' for p in o['paths']]
 if o['bodytype']:args.append(f'Read<{o["bodytype"]}>()')
 if o['multipart']:args+=['"fixture.png"','"image/png"']
 if o['csv']:args+=['destination']
 if o['querytype']:args.append(f'Query<{o["querytype"]}>()')
 args+=['options','cancellationToken'];call=f'client.{o["resource"]}.{o["methodName"]}Async('+', '.join(args)+')'
 if o['csv']:lines += [f'            case "{o["id"]}":', '            {','                using var destination = new MemoryStream();',f'                await {call};','                return System.Text.Encoding.UTF8.GetString(destination.ToArray());','            }']
 elif o['responsetype']:lines+=[f'            case "{o["id"]}": return await {call};']
 else:lines+=[f'            case "{o["id"]}": await {call}; return null;']
lines+=['            default: throw new InvalidOperationException("No invocation for " + operation);','        }','    }','}'];text='\n'.join(lines)+'\n';p=root/'tests/Kirora.Tests/ExtendedEndpointInvoker.g.cs'
if '--check' in sys.argv:
 if not p.exists() or p.read_text()!=text:raise SystemExit('Endpoint invocations are stale')
else:p.write_text(text)
print(f'All {len(ops)} public endpoint invocations match generated contracts.')
